// The one hand-written line every generated function/hook needs: a
// `CratestackRuntime` instance. Everything downstream of this — types,
// fetch calls, SWR hooks, cache keys, invalidation — is generated by
// `--swr` (see `../../client/`); this file is not "data-fetching code",
// it's wiring a base URL, matching the ticket's zero-hand-written-
// data-fetching-code bar.
//
// Imported from the `/swr` subpath, NOT the package root: `--swr` (issue
// #591) nests its own `CratestackRuntime` under `src/swr/runtime.ts`,
// generated from the same template as the default layout's
// `src/runtime.ts` but compiled to a structurally-identical, nominally
// *distinct* class (private fields make TypeScript treat the two as
// incompatible even though every field matches) — every hook this app
// imports (`react-vite-swr-client/swr/models/*.hooks`) expects the `/swr`
// one specifically, so the runtime instance handed to them has to come
// from there too, not the root.
import { CratestackRuntime } from "react-vite-swr-client/swr";
import { session } from "./session.ts";

// Stand-in for real auth (a session cookie, a bearer token, an OAuth
// flow — anything a production app would use). The server's
// `HeaderAuthProvider` (`../../src/auth.rs`) reads `x-auth-id` as
// `auth().id`, and `x-auth-time` / `x-auth-amr` as the principal's
// `auth_time` and `amr` (cratestack#1245). `headers` is a function, read on
// every request, so once the step-up dialog updates the session the
// retried call carries the new values. Building a login screen is out of
// scope for this example.
export const runtime = new CratestackRuntime("http://127.0.0.1:3210", {
  basePath: "/api",
  headers: () => session.headers(),
});
